bool searchMatrix(vector<vector<int>> &matrix, int target)
{
    int n = matrix.size();
    int m = matrix[0].size();
    int low = 0;
    int high = n * m - 1;
    while (low <= high)
    {
        int mid = low + (high - low) / 2;
        int val = matrix[mid / m][mid % m];
        if (val == target)
            return true;
        else if (val > target)
            high = mid - 1;
        else
            low = mid + 1;
    }
    return false;
}

ListNode* middleNode(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }

    return slow;
}

ListNode* reverseList(ListNode* head) {
    ListNode* prev = NULL;
    ListNode* curr = head;
    while (curr) {
        ListNode* frwd = curr->next;
        curr->next = prev;
        prev = curr;
        curr = frwd;
    }
    return prev;
}

bool hasCycle(ListNode *head) {
    ListNode* slow = head;
    ListNode* fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast)
            return true;
    }
    return false;
}

int findFloor(Node* root, int x) {
    if (!root) return -1;
    int ans = -1;
    while (root) {
        if (root->data == x) {
            ans = root->data;
            break;
        } else if (root->data < x) {
            ans = root->data;
            root = root->right;
        } else {
            root = root->left;
        }
    }
    return ans;
}

TreeNode* deleteNode(TreeNode* root, int key) {
    if (!root) return NULL;
    if (root->val == key) {
        if (!root->left && !root->right) return NULL; // Case: Node to be deleted is a leaf node
        if (!root->left || !root->right) return root->left ? root->left : root->right; // Case: Node to be deleted has only one child
        TreeNode* temp = root->left; // Case: Node to be deleted has both left and right children
        while (temp->right != NULL) temp = temp->right;
        root->val = temp->val;
        root->left = deleteNode(root->left, temp->val); // Delete the node that was copied into the current node
    } 
    if (root->val < key) root->right = deleteNode(root->right, key);
    root->left = deleteNode(root->left, key);
    return root;
}
